// The first call returns the hero plus every other section on the page.
const first = $input.first().json
const form = $('Website Rebuild Form').first().json
const framework = ({ 'Tailwind': 'tailwind', 'React': 'jsx', 'HTML + CSS': 'html', 'Vue': 'vue' })[form.Output] || 'tailwind'
const rest = (first.sections || [])
  .filter(s => s.selector !== first.selector)
  .sort((a, b) => a.order - b.order)
  .slice(0, 12)
// A page with only a hero still finishes: the next node repeats the cached (free) hero call.
if (!rest.length) return [{ json: { url: form.Website, framework } }]
return rest.map(s => ({ json: { url: form.Website, framework, selector: s.selector, label: s.label, order: s.order } }))

// Every section call files itself under the page; the newest link holds them all.
const all = [...$('Extract Hero and Find Sections').all(), ...$input.all()].map(i => i.json)
const withPage = all.filter(r => r.pagePreviewUrl)
const page = withPage.length ? withPage[withPage.length - 1].pagePreviewUrl : all[0].previewUrl
return [{ json: { pagePreviewUrl: page, sections: all.filter(r => r.code).length } }]
